[CmdletBinding()]param([Parameter(Mandatory)][uri]$BaseUrl,[string]$OutputPath='smoke-tests.json')
$ErrorActionPreference='Stop';$tests=@();foreach($path in '/health/live','/health/ready','/Account/Login','/favicon.ico','/Labels/History','/Labels/LocDesk','/Labels/PrintWizard?subjectType=DOCUMENT&mode=CUSTOM'){try{$r=Invoke-WebRequest ([uri]::new($BaseUrl,$path)) -UseBasicParsing -MaximumRedirection 0 -SkipHttpErrorCheck;$body=[string]$r.Content;$tests+=[pscustomobject]@{path=$path;passed=$r.StatusCode-lt500-and$body-notmatch'(?i)stack trace|exception at ';status=$r.StatusCode}}catch{$tests+=[pscustomobject]@{path=$path;passed=$false;status=0}}};$report=[pscustomobject]@{passed=-not($tests|Where-Object{-not$_.passed});testedAtUtc=[DateTime]::UtcNow.ToString('o');tests=$tests};$report|ConvertTo-Json -Depth 6|Set-Content $OutputPath;if(-not$report.passed){exit 2}
